import subprocess,sys,json,hashlib
from pathlib import Path
r=Path('.agent-runs/performance-v2');python=r/'automl-env/Scripts/python.exe'
work=[]
for seed in range(2201,2204):
 for model in (['svm','lightgbm'] if seed%2 else ['lightgbm','svm']):
  for budget in (['1','5'] if seed%2 else ['5','1']):
   for label in (['baseline','current'] if seed%2 else ['current','baseline']):work.append((label,seed,model,budget))
work += [(label,2204,'svm',budget) for budget in ['control_features','control_gasearch'] for label in ['baseline','current']]
for label,seed,model,budget in work:
 name=f'feature-timer-{label}-{model}-{budget}-{seed}';print('START',name,flush=True)
 with (r/(name+'.log')).open('w',encoding='utf-8') as out:
  result=subprocess.run([str(python),str(r/'feature_timer_worker.py'),label,str(seed),model,budget],stdout=out,stderr=subprocess.STDOUT,timeout=900)
 print('EXIT',name,result.returncode,flush=True)
 if result.returncode:sys.exit(result.returncode)
manifest=json.loads((r/'feature-timer-source-sha256.json').read_text(encoding='utf-8'))
for label,paths in manifest.items():
 for path,sha in paths.items():assert hashlib.sha256((r/f'feature-timer-{label}'/path).read_bytes()).hexdigest()==sha,path
print('All136fits complete; immutable sources unchanged',flush=True)
